SELECT status, CASE WHEN monthly_fee >= 244 THEN 'high' WHEN monthly_fee >= 114 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, SUM(CASE WHEN plan = 'enterprise' THEN 1 ELSE 0 END) AS enterprise_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values, MIN(start_date) AS min_start_date FROM subscriptions WHERE end_date >= '2024-08-01' AND status NOT IN ('EXPIRED', 'CANCELLED') AND end_date <= '2025-05-01' GROUP BY status, CASE WHEN monthly_fee >= 244 THEN 'high' WHEN monthly_fee >= 114 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN plan = 'enterprise' THEN 1 ELSE 0 END) > 33 ORDER BY 1 DESC, min_start_date;
